export function getProvinceDisplayName(province, locale) {
  if (!province) return ''
  if (locale === 'zh') return province.name
  return PROVINCE_EN_BY_CODE[province.code] ?? province.name
}

export function getCityDisplayName(city, locale) {
  if (!city) return ''
  if (locale === 'zh') return city.name
  return CITY_EN_BY_ZH[city.name] ?? city.name
}

/** Resolve display name when only code + Chinese name are available (e.g. heatmap entries). */
export function getProvinceDisplayNameByCode(code, zhName, locale) {
  if (locale === 'zh') return zhName
  return PROVINCE_EN_BY_CODE[code] ?? zhName
}
